def match_pubdate(node: etree._Element, pubdate_xpaths: list[str]) -> Optional[str]:
    """For the given node, returns the first match in the pubdate_xpaths list."""
    for xpath in pubdate_xpaths:
        result = node.xpath(xpath)
        if result:
            return result[0]
    return None

