from typing import List, Dict
from collections import defaultdict
import logging

def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Given a list of dictionaries, returns a new dictionary where the values of the same keys are summed up.

    Args:
        dicts (List[Dict[str, int]]): A list of dictionaries with string keys and integer values.

    Returns:
        Dict[str, int]: A dictionary with summed values for each key.
    """
    result = defaultdict(int)

    for d in dicts:
        for key, value in d.items():
            if isinstance(value, int):
                result[key] += value
            else:
                logging.error(f"Non-integer value encountered for key '{key}': {value}")

    return result

