from types import ModuleType
import importlib.util
import sys


def _is_submodule(parent_module_name: str, child_module_name: str) -> bool:
    """Check if child_module_name is a submodule of parent_module_name."""
    return child_module_name.startswith(parent_module_name + ".")


def _get_all_modules() -> set[str]:
    """Get all loaded modules."""
    return {m.__name__ for m in sys.modules.values() if isinstance(m, ModuleType)}


def _get_module_from_name(module_name: str) -> ModuleType | None:
    """Get a module by its name."""
    try:
        return sys.modules[module_name]
    except KeyError:
        return None


def _get_classes_in_module(module: ModuleType) -> set[type]:
    """Get all classes defined in a module."""
    return {
        obj
        for name, obj in vars(module).items()
        if isinstance(obj, type)
    }


def subclasses(cls: type) -> list[type]:
    """Recursively find all subclasses of a given class, including those defined in imported modules."""
    direct_subclasses = cls.__subclasses__()
    all_subclasses = set()

    # Collect direct subclasses
    all_subclasses.update(direct_subclasses)

    # Collect indirect subclasses
    for subclass in direct_subclasses:
        all_subclasses.update(subclasses(subclass))

    # Track processed modules to avoid circular imports
    processed_modules = set()

    # Collect subclasses from imported modules
    for module_name in _get_all_modules():
        if _is_submodule(cls.__module__, module_name):
            module = _get_module_from_name(module_name)
            if module and module_name not in processed_modules:
                processed_modules.add(module_name)
                classes_in_module = _get_classes_in_module(module)
                for class_ in classes_in_module:
                    if issubclass(class_, cls) and class_ not in all_subclasses:
                        all_subclasses.add(class_)
                        all_subclasses.update(subclasses(class_))

    return list(all_subclasses)

